/**
 * config.js — Application configuration
 * 
 * DECISION: Using a runtime config object rather than build-time env vars,
 * since this is a static HTML/JS app with no build step. To switch to a
 * real backend, change API_BASE_URL here and remove the MOCK_MODE flag.
 * 
 * For production, this file could be generated by CI/CD or replaced by
 * a fetched /config.json at load time for true environment isolation.
 */

