    PHONE: '+923001234567',           // CHANGE: real WhatsApp number
    WHATSAPP_NUMBER: '923001234567',  // No + or spaces for wa.me URL
    EMAIL: 'info@sandhuinstallments.com',
    ADDRESS: 'Lahore, Punjab, Pakistan',
