/**
 * Format a number as PKR currency.
 * @param {number} amount
 * @param {boolean} [compact=false] — use 1.2M, 45K style
 */
export function formatCurrency(amount, compact = false) {
  if (amount === null || amount === undefined) return '—';
  if (compact) {
    if (amount >= 1_000_000) return `PKR ${(amount / 1_000_000).toFixed(1)}M`;
    if (amount >= 1_000)     return `PKR ${(amount / 1_000).toFixed(0)}K`;
  }
  return new Intl.NumberFormat(Config.BUSINESS.CURRENCY_LOCALE, {
    style: 'currency',
    currency: Config.BUSINESS.CURRENCY,
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(amount);
}

/** Format a date string to a readable date */
export function formatDate(dateStr) {
  if (!dateStr) return '—';
  return new Date(dateStr).toLocaleDateString('en-PK', {
    year: 'numeric', month: 'short', day: 'numeric',
  });
}

/** Format a date as relative time ("3 days ago", "in 2 days") */
export function formatRelativeDate(dateStr) {
  if (!dateStr) return '—';
  const now = new Date();
  const date = new Date(dateStr);
  const diffMs = date - now;
  const diffDays = Math.round(diffMs / (1000 * 60 * 60 * 24));

  if (diffDays === 0) return 'Today';
  if (diffDays === 1) return 'Tomorrow';
  if (diffDays === -1) return 'Yesterday';
  if (diffDays > 0) return `In ${diffDays} days`;
  return `${Math.abs(diffDays)} days ago`;
}

/** Get initials from a full name */
export function getInitials(name) {
  if (!name) return '?';
  const parts = name.trim().split(' ');
  if (parts.length === 1) return parts[0][0].toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

/** Debounce helper */
export function debounce(fn, ms = 300) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), ms);
  };
}

/** Capitalize first letter, replace dashes with spaces */
export function capitalize(str) {
  if (!str) return '';
  return str.charAt(0).toUpperCase() + str.slice(1).replace(/-/g, ' ');
}

/** Generate a badge CSS class suffix from a status string */
export function getStatusClass(status) {
  const map = {
    active: 'active',
    inactive: 'inactive',
    blacklisted: 'danger',
    paid: 'paid',
    pending: 'pending',
    overdue: 'overdue',
    'due-soon': 'due-soon',
    completed: 'paid',
    defaulted: 'danger',
    cancelled: 'inactive',
  };
  return map[status] || 'info';
}
